// Manuscript content (revision 3). All numbers are read from ../data/results.json (model.py).
// Inline markup: **bold**, *italic*, ~subscript~, ^superscript^. Block types: h1, h2, h3, p, eq, table, fig, balance.
const path = require("path");
const R = require(path.join(__dirname, "..", "data", "results.json"));
const c = R.central, mc = R.mc, d = R.decomp, cal = R.calib, val = R.valid;

const f = (x, dp = 0) => Number(x).toLocaleString("en-US", { minimumFractionDigits: dp, maximumFractionDigits: dp });
const ci = (k, dp = 0) => `${f(mc[k].p5, dp)}–${f(mc[k].p95, dp)}`;
const pct = (a, b, dp = 1) => f((a / b) * 100, dp);
const F = (n, file, caption) => ({ type: "fig", n, file, caption });
const s = c.sectors, es = c.elec_sec, co2 = c.co2;
const petInd = s["Industrial"] - c.ind_fuel - c.coal - es["Industrial"];
const petRes = s["Residential"] - es["Residential"];
const tfcProd = c.domestic_prod - c.jet_intl;
const ts24 = R.ts.find((t) => t.year === 2024), ts15 = R.ts.find((t) => t.year === 2015);
const subsidyUSD = 0.520 * 2.6008;
const ea = Object.entries(co2).filter(([k]) => k.startsWith("1.A.1")).reduce((a, [, v]) => a + v, 0);
const newCats = co2["1.A.1.b Petroleum refining"] + co2["1.A.1.c LNG liquefaction"] + co2["1.A.1.c Oil & gas extraction"];
const st = Object.fromEntries(R.steps.map(([k, v]) => [k, v]));
const ref = val.refinery;
const sdKbd = -c.sd_crude / 0.136 / 365;
const rent30 = (p) => (0.3 * 50973.5 * 3.6 / 0.45 / 41.868) * 39.683e3 / 0.9 * (p * c.eta_lng - 1 - 3) / 1e9;
const gcpCal = cal.co2_total_gcp_cal;

const meta = {
  title:
    "Closing the books of a rentier energy economy: reconciled energy accounts, CO₂ drivers and the renewable dual dividend in Oman, 2015–2025",
  runningTitle: "Reconciled energy accounts for Oman",
  highlights: [
    `Plant-level checks locate a ${f(sdKbd)} kb/d crude-supply gap in Oman's refinery data.`,
    `On a net-calorific basis, 2025 primary supply is ${f(c.tpes / 1000, 1)} Mtoe (90% CI ${f(mc.tpes.p5 / 1000, 1)}–${f(mc.tpes.p95 / 1000, 1)}).`,
    `Combustion CO₂ is ${f(c.co2_total)} Mt (${ci("co2_total")} Mt); oil-field gas use dominates uncertainty.`,
    `Population and energy intensity drove CO₂ up ${f(d["2015-2024"].total, 1)} Mt over 2015–2024.`,
    `Domestic gas use carries an implicit rent of about ${f(c.rent_share_gdp, 0)}% of GDP a year.`,
  ],
  abstract:
    `Hydrocarbon exporters face a distinctive decarbonization problem: the fuels displaced at home are also the source of fiscal rents abroad, and the energy statistics needed to manage this trade-off are often internally inconsistent. This study applies standard compilers' checks (column closure, plant-level process closure and an explicit separation of calibration from validation) to Oman's 2025 national energy accounts and links the reconciled balance to rent incidence. The checks show that reported refinery output is consistent with plant capacities but exceeds recorded crude supply by about ${f(sdKbd)} kb/d. They also show that the reported LNG feedstock is implausible on a consistent net-calorific basis, and that reinjected gas and chemical feedstock had been counted as fuel. On a net-calorific basis, indigenous production is ${f(c.production)} ktoe and use-side Total Primary Energy Supply ${f(c.tpes)} ktoe (90% CI ${ci("tpes")}), giving a self-sufficiency ratio of ${f(c.ssr, 0)}%. Fuel-combustion CO₂ emissions are ${f(c.co2_total, 1)} Mt (${ci("co2_total", 1)}), ${pct(c.co2_fuel["Natural gas"], c.co2_total, 0)}% from natural gas. A logarithmic mean Divisia index decomposition of 2015–2024 attributes the rise in emissions to population growth (+${f(d["2015-2024"].pop, 1)} Mt) and energy intensity (+${f(d["2015-2024"].ei, 1)} Mt). Renewables supplied ${f(c.re_share_gen, 2)}% of electricity in 2025, avoiding ${ci("avoided", 1)} MtCO₂ and freeing about 1 bcm of gas. Domestic gas combustion carries an implicit rent of about ${f(c.rent_share_gdp, 0)}% of GDP, far larger than the rent renewables currently preserve. Transparent energy accounts are a precondition for credible decarbonization in rentier states.`,
  keywords: ["Energy balance reconciliation", "Rentier state", "LMDI decomposition", "Monte Carlo uncertainty",
    "Natural gas rents", "Oman"],
};

const abbreviations = [
  ["bcm", "Billion cubic metres"], ["CI", "Confidence interval (5th–95th percentile)"],
  ["EF", "Emission factor"], ["EI", "Energy Institute"], ["EOR", "Enhanced oil recovery"],
  ["GCC", "Gulf Cooperation Council"], ["GCP", "Global Carbon Project"], ["GCV", "Gross calorific value"],
  ["IPCC", "Intergovernmental Panel on Climate Change"],
  ["IRES", "International Recommendations for Energy Statistics"], ["kbbl; kb/d", "Thousand barrels; thousand barrels per day"],
  ["ktoe", "Thousand tonnes of oil equivalent, net calorific basis (1 toe = 41.868 GJ)"], ["LMDI", "Logarithmic mean Divisia index"],
  ["LNG", "Liquefied natural gas"], ["MMBtu", "Million British thermal units (gross basis)"], ["MMscf", "Million standard cubic feet"],
  ["NCV", "Net calorific value"], ["NDC", "Nationally Determined Contribution"],
  ["OPWP", "Oman Power and Water Procurement Company"], ["SD", "Statistical difference"],
  ["SSR", "Self-sufficiency ratio (production ÷ TPES)"], ["TFC", "Total Final Consumption"],
  ["TPES", "Total Primary Energy Supply"], ["VRE", "Variable renewable energy"],
];

const body = [
  // ================================================================== 1
  { type: "h1", text: "1. Introduction" },
  { type: "h2", text: "1.1. Background" },
  { type: "p", text: "The economies of the Gulf Cooperation Council (GCC) are organised around the capture and redistribution of hydrocarbon rents. In the rentier-state model, external rents accrue directly to the state, which allocates them domestically through public employment, transfers and administered energy prices rather than through taxation (Beblawi and Luciani, 1987; Krane, 2019). The fiscal architecture that sustains political stability also locks in high domestic energy demand: subsidised electricity and fuels have produced per-capita consumption and energy intensities among the highest in the world (Lahn and Stevens, 2011; Fattouh and El-Katiri, 2013; Al-Badi and AlMubarak, 2019). Climate change adds structural pressure in a region already exposed to extreme heat and water stress (Al-Maamary et al., 2017a)." },
  { type: "p", text: "The Sultanate of Oman occupies a specific position within this group. It is a mid-sized producer with modest reserves and a history of fiscal deficits, so the opportunity cost of domestic hydrocarbon use is particularly salient (Al-Sarihi and Cherni, 2023). Oman Vision 2040 formalises a pivot towards economic diversification and a low-carbon energy sector. The government has pledged net-zero emissions by 2050 and has updated its Nationally Determined Contribution (NDC) (Sultanate of Oman, 2020, 2021; Argus Media, 2023). The Oman Power and Water Procurement Company (OPWP) targets a 30% renewable share of generation by 2030, and the state-owned Hydrogen Oman (Hydrom) is mandated to develop 1.0–1.25 Mt of renewable hydrogen per year by 2030 (IEA, 2023b; OPWP, 2024)." },
  { type: "h2", text: "1.2. Problem statement" },
  { type: "p", text: "Heavily subsidised, centralised petroleum economies exhibit considerable structural inertia. Incumbent institutions, administered prices and long-term export contracts tend to delay the diffusion of renewables even where resources are exceptional (Al-Sarihi and Cherni, 2023; Szalai et al., 2025). A less frequently discussed barrier is informational. Energy and climate policy rests on a national energy balance that traces energy from production and trade through transformation to final use. The balance supplies activity data for emissions inventories, denominators for efficiency indicators and the evidence base for subsidy and investment decisions (UNSD, 2018; Nagovnak et al., 2022)." },
  { type: "p", text: "Energy balances of hydrocarbon exporters are unusually difficult to compile. Large transformation sectors (refining, liquefaction and gas-fired power-and-water plants) dominate the accounts, so small errors in conversion factors, calorific bases or flow definitions propagate into large errors in primary supply. Gas reinjected for pressure maintenance must be separated from gas that is burnt, gas used as chemical feedstock from gas used as fuel, and data compiled on gross and net calorific bases must be harmonised (Neelis and Pouwelse, 2008; UNSD, 2018). Administrative data are fragmented across ministries and companies (Kuunifaa et al., 2026). A balance whose columns sum correctly can therefore still violate physical constraints." },
  { type: "h2", text: "1.3. Literature review" },
  { type: "p", text: "Four strands of literature frame this study. The first concerns the relationship between growth, energy use and emissions. The Environmental Kuznets Curve (EKC) hypothesis posits an inverted-U relationship between income and environmental pressure (Grossman and Krueger, 1995), but its empirical robustness has been widely questioned (Stern, 2004). For the GCC, panel and time-series studies generally find that energy consumption and emissions remain tightly coupled to growth (Al-Iriani, 2006; Salahuddin and Gow, 2014; Bekhet et al., 2017; Abdel-Gadir and Mohammed, 2024). Index decomposition analysis, in particular the logarithmic mean Divisia index (LMDI), is the standard tool for attributing emission changes to scale and intensity effects (Ang, 2015), yet it has rarely been applied to Oman." },
  { type: "p", text: "The second strand addresses the political economy of transition in producer states. Self-sufficiency captures availability but not affordability, sustainability or governance (Sovacool and Mukherjee, 2011; Ang et al., 2015). For exporters, the transition both threatens rents and creates opportunities to monetise low-cost renewable electricity and hydrogen (Goldthau and Westphal, 2019; Gielen et al., 2019). Studies of Oman and the United Arab Emirates show that renewables have been rationalised partly as a means of preserving hydrocarbons for export, attracting investment and projecting a modernised image (Al-Maamary et al., 2017b; Szalai et al., 2025). Using strategic niche management, Al-Sarihi and Cherni (2023) argue that the Omani state supports renewable projects selectively, in ways that preserve the hydrocarbon regime. Regional and national reviews document targets, readiness gaps and resource potential (Al-Badi et al., 2011; Mondal et al., 2016; Praveen et al., 2020; Almasri and Narayan, 2021; Amoatey et al., 2022; Marzouk, 2024; Leal-Arcas et al., 2025)." },
  { type: "p", text: "The third strand concerns the integration of variable renewable energy (VRE) into thermal grids. As VRE penetration rises, its market value declines and flexibility requirements grow (Denholm and Hand, 2011; Hirth, 2013). In Oman, multi-criteria assessments favour pumped hydro and compressed air storage (Al-Abri et al., 2024), and distributed photovoltaics face financial, technical and awareness barriers (Mishrif and Khan, 2024; Venkatachalam et al., 2025). Transition theory locates such barriers in regimes of institutions, infrastructure and practice rather than in technology alone (Geels, 2002; Sovacool, 2016)." },
  { type: "p", text: "The fourth strand is energy statistics. Nagovnak et al. (2022) show that IRES-based balances must be adapted to capture transition-era flows. Neelis and Pouwelse (2008) document how feedstock and combustion uses are confused in industrial statistics. Liu et al. (2026) show that territorial Tier 1 accounting misattributes emissions associated with traded fuels, and studies of emerging economies document fragmented activity data and weak quality assurance in national inventories (Kuunifaa et al., 2026). Table 1 summarises the studies most relevant here." },
  { type: "table", n: 1, caption: "Synthesis of the literature most relevant to this study.", widths: [2000, 1500, 2700, 3160],
    header: ["Study", "Scope", "Approach", "Relevance to this study"],
    rows: [
      ["Nagovnak et al. (2022)", "Austria", "IRES balance methodology for the energy transition", "Template for matrix structure and flow diagrams"],
      ["Neelis and Pouwelse (2008)", "Netherlands", "Reconciling feedstock and combustion in industrial statistics", "Precedent for separating feedstock and non-energy use"],
      ["Ang (2015)", "Methodological", "LMDI decomposition guide", "Decomposition of CO₂ drivers, 2015–2024"],
      ["Al-Sarihi and Cherni (2023)", "Oman", "Political economy of renewables in a rentier state", "Interpretive frame for rent incidence"],
      ["Szalai et al. (2025)", "UAE, Oman", "Political economy of renewable deployment", "Renewables as rent preservation"],
      ["Salahuddin and Gow (2014); Bekhet et al. (2017)", "GCC", "Econometric growth–energy–emissions nexus", "Evidence of persistent coupling"],
      ["Charabi et al. (2018)", "Oman", "GHG reduction pathways for a hydrocarbon economy", "Policy context for NDC tracking"],
      ["Liu et al. (2026)", "Global", "Origin of traded fuels in combustion CO₂ accounting", "Limits of Tier 1 territorial accounting"],
    ] },
  { type: "h2", text: "1.4. Research gap and contribution" },
  { type: "p", text: "International agencies already publish energy data for Oman: the IEA and the United Nations Statistics Division compile balances from national questionnaire returns, and the Energy Institute (EI) and the Global Carbon Project (GCP) report aggregate energy and emission series (IEA, 2023a; Energy Institute, 2025; Our World in Data, 2026). These products do not document how national source data are reconciled. Oman-specific studies rely on them, and none tests the physical consistency of the underlying accounts, quantifies their uncertainty or links them to the distribution of hydrocarbon rents (Charabi et al., 2018; Abdel-Gadir and Mohammed, 2024)." },
  { type: "p", text: "The closure checks used here are routine for IEA and Eurostat compilers; the paper does not claim them as new. Its contributions are four applications. First, it applies plant-level closure checks to a producer state's national accounts, with an explicit separation between parameters calibrated to external data and tests against data not used in calibration. Second, it publishes the resulting reconciled 2025 balance for Oman, with every correction documented and the remaining uncertainty propagated by Monte Carlo simulation. Third, it places 2025 in a 2015–2024 context through an LMDI decomposition of CO₂ emissions. Fourth, it uses the reconciled accounts to quantify rent incidence: the implicit gas rent transferred to domestic users and the rent preserved by renewables, the “dual dividend”. Section 2 describes data and methods, Section 3 the results, Section 4 the political economy of the transition, Section 5 policy implications and limitations, and Section 6 concludes." },

  // ================================================================== 2
  { type: "h1", text: "2. Data and methods" },
  { type: "p", text: "Fig. 1 summarises the research design. A failed closure test triggers re-harmonisation of the source data; gaps that cannot be resolved with available data are reported explicitly as statistical differences rather than imputed." },
  F(1, "Fig01_framework.png", "Research design: activity data, harmonisation, closure, calibration and validation, and analysis."),
  { type: "h2", text: "2.1. Accounting framework, closure tests and calibration" },
  { type: "p", text: "We follow the International Recommendations for Energy Statistics (UNSD, 2018), mirrored in IEA and Eurostat practice (IEA, 2023a; Eurostat, 2021). For each commodity *c*, supply-side Total Primary Energy Supply is:" },
  { type: "eq", n: 1, text: "TPES~c~ = P~c~ + M~c~ − X~c~ − B~c~ ± ΔS~c~" },
  { type: "p", text: "where *P* is indigenous production, *M* imports, *X* exports, *B* international marine and aviation bunkers and Δ*S* the stock change. Final consumption follows from:" },
  { type: "eq", n: 2, text: "TFC~c~ = TPES~c~ − TI~c~ + TO~c~ − OU~c~ − L~c~ − SD~c~" },
  { type: "p", text: "where *TI* and *TO* are transformation inputs and outputs, *OU* energy-sector own use, *L* distribution losses and *SD* the statistical difference. Test T1 inspects *SD*~c~. Test T2 requires the apparent efficiency of each transformation process *k*, evaluated plant by plant where data allow, to be physically plausible:" },
  { type: "eq", n: 3, text: "η~k~ = Σ~c~ TO~c,k~ / Σ~c~ TI~c,k~ ,   0 < η~k~ < η~k~^max^" },
  { type: "p", text: "Parameters that cannot be measured are either calibrated to an external dataset (C) or bounded by engineering ranges. Agreement with a dataset used for calibration is not treated as evidence of accuracy. Independent validation (V) uses only external data that do not enter the calibration: crude and condensate production, oil consumption and electricity generation. External 2024 values are extrapolated to 2025 with their 2019–2024 compound growth rates to remove the year mismatch. Following IRES, primary electricity comprises only solar and wind, reinjected gas is excluded from production, and all quantities are expressed on a net calorific value (NCV) basis (UNSD, 2018)." },
  { type: "h2", text: "2.2. Data" },
  { type: "p", text: "Table 2 lists the data sources. All 2025 activity data are official national statistics or company data submitted to the national statistical system; 2015–2025 external series are from public international datasets." },
  { type: "table", n: 2, caption: "Data sources.", widths: [2700, 4460, 2200], header: ["Source", "Data", "Coverage"],
    rows: [
      ["National Centre for Statistics and Information (NCSI, 2026)", "Crude and condensate production and exports; Sohar and Mina Al Fahal output by product; gas production and use by category; LNG exports; electricity; GDP; population", "2021–2025"],
      ["Ministry of Energy and Minerals", "Monthly production; gas use by sector", "2025"],
      ["Duqm refinery operator", "Refinery output; foreign crude imports; product exports", "2025"],
      ["Renewable Energy Bulletin", "Monthly renewable generation by plant", "2022–2025"],
      ["Customs; port bunkering records", "Coal (HS 2701) and lignite (HS 2704) trade; marine bunkers", "2025"],
      ["EI, GCP and Ember via Our World in Data", "Primary energy, gas and oil consumption, CO₂ by fuel, electricity, population, GDP", "2015–2025"],
      ["Industry sources", "Refinery and chemical-plant capacities; production and export estimates", "2024–2026"],
      ["IPCC (2006)", "Default NCVs and CO₂ emission factors", "International default"],
    ] },
  { type: "h2", text: "2.3. Calorific basis and conversion factors" },
  { type: "p", text: `The national gas factor (0.02549 ktoe/MMscf) corresponds to about 1,012 Btu/scf, a gross calorific value (GCV). Because the IPCC emission factors are NCV-based, all gas quantities are converted to NCV with the conventional ratio NCV = 0.9 × GCV (UNSD, 2018). Crude oil is converted at 0.136 ktoe/kbbl. Refined products use product-specific factors from IPCC (2006) NCVs and typical densities (Appendix B), giving ${f(R.f_slate, 4)} ktoe/kbbl for the Sohar and Mina Al Fahal slate. Duqm, which has no product breakdown, is assigned ${f(c.f_duqm, 3)} ktoe/kbbl (range 0.125–0.135), reflecting its middle-distillate design. LNG is converted at ${f(R.lng_toe_t, 3)} toe/t (NCV ≈ 49.3 GJ/t), electricity at its physical energy content and coal at 0.65 ktoe/kt (Table 3).` },
  { type: "table", n: 3, caption: "Conversion factors (NCV basis).", widths: [2600, 1500, 2300, 2960], header: ["Commodity", "Unit", "Factor", "Basis"],
    rows: [
      ["Crude oil and condensate", "kbbl", "0.136 ktoe/kbbl", "National crude assay"],
      ["Products: Sohar + Mina Al Fahal", "kbbl", `${f(R.f_slate, 4)} ktoe/kbbl`, "Product-specific (Appendix B)"],
      ["Products: Duqm", "kbbl", `${f(c.f_duqm, 3)} ktoe/kbbl`, "Middle-distillate slate; U(0.125, 0.135)"],
      ["Natural gas", "MMscf", "0.02549 × 0.9 = 0.02294 ktoe/MMscf", "GCV ≈ 1,012 Btu/scf; NCV = 0.9 GCV"],
      ["LNG", "t", `${f(R.lng_toe_t, 3)} toe/t`, "NCV ≈ 49.3 GJ/t"],
      ["Coal and lignite", "t", "0.00065 ktoe/t", "IPCC-consistent default"],
      ["Electricity", "GWh", "0.086 ktoe/GWh", "Physical energy content"],
    ] },
  { type: "h2", text: "2.4. Reconciliation procedures" },
  { type: "h3", text: "2.4.1. Refinery and crude oil" },
  { type: "p", text: `National data report two refinery figures. The product-resolved output of 115,140 kbbl (${f(c.out_sm)} ktoe) published by NCSI covers only the Sohar and Mina Al Fahal system. The total of 210,833 kbbl also includes Duqm's output of 95,693 kbbl (${f(c.out_dq)} ktoe), reported by the operator without product detail. Each figure is consistent with its plant's capacity (Fig. 3a). Sohar and Mina Al Fahal produced ${f(ref[0].out_kbd)} kb/d against a combined nameplate of ${ref[0].cap_kbd} kb/d (198 and 106 kb/d). Duqm produced ${f(ref[1].out_kbd)} kb/d against 255 kb/d after its 2025 debottlenecking (Oxford Business Group, 2019; QCIntel, 2025; Argus Media, 2025). The 2–4% excess in each case equals the volume gain expected when crude is converted into lighter products. At a net refinery energy efficiency η~ref~ of 0.95 (0.92–0.98; Szklo and Schaeffer, 2007), the implied crude intake is ${f(c.ref_intake)} ktoe, or ${f(val.intake_kbd)} kb/d, about 102% of nameplate. This agrees with operator reports of running above nameplate.` },
  { type: "p", text: `Recorded crude supply to refineries (production − exports + imports) is only ${f(c.crude_supply)} ktoe (${f(val.crude_supply_kbd)} kb/d), so a gap of ${f(-c.sd_crude)} ktoe (${f(sdKbd)} kb/d) remains. Three explanations were tested. (H0) Refinery output is double-counted. This is rejected because each plant group's output is consistent with its own capacity. The rejection also holds against the special case of symmetric double counting of output and exports: Duqm's product breakdown is not in the NCSI slate, so its output cannot have been counted twice in the 210,833 kbbl total. (H1) Crude exports are over-recorded. This is not supported, because the export series (844 kb/d) is consistent with IMF-sourced estimates of 830–842 kb/d and OPEC-sourced estimates of about 897 kb/d (FRED, 2025; CEIC, 2026). (H2) Crude production is under-recorded. This is also rejected: recorded production (${f(val.production_kbd)} kb/d) matches independent estimates of crude (775 kb/d) plus condensate (233 kb/d) (Energy Intelligence, 2025; CEIC, 2026). The location of the gap therefore cannot be identified with public data. Candidate explanations include crude imports for Duqm beyond those recorded, draws on the Ras Markaz strategic storage, and terminal liftings to domestic refineries that are recorded as exports.` },
  { type: "p", text: `Following IEA practice, we do not attribute the gap. Instead, we carry it as an explicit statistical difference (SD) in the crude oil column and report two TPES measures. Supply-side TPES (Eq. 1) uses recorded trade and production. Use-side TPES adds back the crude SD and is anchored on physically observed refinery throughput. Use-side TPES is the central measure because it is consistent with plant capacity, observed domestic product use and independent oil consumption data (Section 3.2).` },
  { type: "h3", text: "2.4.2. Natural gas: LNG, feedstock, oil fields and power-and-water plants" },
  { type: "p", text: `Gross production is ${f(c.gas_gross)} ktoe (NCV). The reported LNG feedstock (599,187 MMscf, or ${f(c.lng_feed_reported)} ktoe NCV) implies a liquefaction efficiency of ${f(c.eta_lng_reported * 100, 1)}% when set against 11.3 Mt of LNG (${f(c.lng_out)} ktoe). This is implausible, because plants consume 7–12% of feed gas as fuel (Lee et al., 2018). We therefore derive feed gas from LNG output and an efficiency of ${f(c.eta_lng * 100, 1)}% (88–93%), which gives ${f(c.lng_feed)} ktoe. National statistics combine LNG feed and industrial gas in one “industrial projects and zones” category. Industrial gas is that category less LNG feed (${f(c.gas_industry)} ktoe). Of this, an estimated ${f(c.chem)} ktoe (1,400–2,300) is feedstock for methanol and ammonia. The estimate rests on about 2 Mt of methanol capacity at Sohar and Salalah and about 2 Mt of ammonia capacity at Sur and Sohar, each requiring roughly 20 GJ of feedstock gas per tonne (IEA, 2021; Proman, 2024; Mitsubishi Heavy Industries, 2009; Oman Observer, 2026). Feedstock gas is recorded as non-energy use and excluded from combustion CO₂. Process CO₂ from ammonia production belongs to IPCC category 2.B and is outside the scope of this inventory.` },
  { type: "p", text: `Gas delivered to oil fields (${f(c.gas_oilfield)} ktoe) is partly burnt and partly reinjected. The burnt share covers thermal enhanced oil recovery (EOR) steam at Amal, Qarn Alam and Mukhaizna, compression and upstream power generation; the rest is reinjected for pressure maintenance. National statistics do not separate the two. We calibrate the combusted share so that domestic gas consumption matches the EI series extrapolated to 2025 on its gross basis (Energy Institute, 2025), converted to NCV. This gives ${f(c.own_share * 100, 0)}% (${f(c.own)} ktoe), within our order-of-magnitude engineering estimate of 3–4.5 Mtoe for thermal EOR steam and upstream power demand. The calibration is sensitive to the external dataset. If EI gas data were on an NCV basis, the share would be ${f(cal.own_share_ei_ncv * 100, 0)}%; calibrating instead to GCP gas CO₂ gives ${f(cal.own_share_gcp * 100, 0)}%. The Monte Carlo analysis therefore draws the share from a triangular distribution between 20% and 75% with mode ${f(c.own_share * 100, 0)}%, and we report the GCP calibration as an alternative case. Reinjected gas (${f(c.reinj)} ktoe centrally) is excluded from production.` },
  { type: "p", text: `If all gas delivered to power-and-water plants (${f(c.gas_power)} ktoe) were attributed to the 46,464.5 GWh of thermal generation, the fleet efficiency would be ${f(c.eta_pp_implied * 100, 1)}% on an NCV basis. This is implausible for a fleet dominated by combined-cycle plants. Integrated plants also supply heat for thermal desalination, and the reported gas may include auxiliary and captive use. Pending a metered split, we attribute to grid electricity the fuel implied by a net fleet efficiency of 45% (40–50%), namely ${f(c.gas_grid)} ktoe. The remaining ${f(c.gas_pw_other)} ktoe is reported as “desalination heat and unattributed”; its emissions remain in the inventory but do not inflate the electricity emission factor.` },
  { type: "h3", text: "2.4.3. Petroleum products" },
  { type: "p", text: `Domestic product availability after exports (${f(c.prod_exp)} ktoe) and marine bunkers (${f(c.bunk_marine, 1)} ktoe) is ${f(c.domestic_prod)} ktoe. Retail sales by product (43,699.8 kbbl) are allocated directly. Gasoline goes to road transport. Diesel is split between transport (70%), industry (15%) and households (5%). Jet fuel goes to aviation, and an estimated 90% of it (80–95%) is international and recorded as bunkers (${f(c.jet_intl)} ktoe). The non-retail remainder (${f(c.residual)} ktoe) is allocated in proportion to the non-retail part of the refinery slate. Naphtha and other products are treated as non-energy use (petrochemical feedstock, bitumen, lubricants) with a share of 0.8 (0.6–1.0). LPG goes to households (70%; 50–90%) and industry, and fuel oil to industry.` },
  { type: "h2", text: "2.5. Emissions" },
  { type: "p", text: "We estimate territorial combustion CO₂ with the IPCC (2006) Tier 1 method on an NCV basis (Appendix A):" },
  { type: "eq", n: 4, text: "E~k,f~ = A~k,f~ × EF~f~" },
  { type: "p", text: "where *A* is the fuel combusted in IPCC source category *k*: electricity and desalination (1.A.1.a), refining (1.A.1.b), LNG liquefaction and upstream fuel (1.A.1.c), manufacturing (1.A.2), transport (1.A.3) and residential use (1.A.4). Flaring, venting, fugitive and process emissions are outside the scope of the inventory. Emissions avoided by renewables are estimated as:" },
  { type: "eq", n: 5, text: "ΔE = G~RE~ × EF~marg~ ,   EF~marg~ = 56.1 kgCO₂/GJ × 3.6 / η~marg~" },
  { type: "p", text: "where η~marg~ is the net efficiency of the gas-fired plant displaced by solar output. It is set at 0.45 centrally and bounded by the efficiencies of open-cycle (0.35) and combined-cycle (0.55) units in Oman's fleet (OPWP, 2024). Gas freed by renewables is *G*~RE~ × 3.6/η~marg~." },
  { type: "h2", text: "2.6. Uncertainty analysis" },
  { type: "p", text: "We propagate parameter uncertainty with 10,000 Monte Carlo draws (Table 4) and report central estimates with 90% intervals. Spearman rank correlations identify the parameters that dominate the uncertainty." },
  { type: "table", n: 4, caption: "Uncertain parameters in the Monte Carlo analysis.", widths: [3300, 1500, 2200, 2360],
    header: ["Parameter", "Central", "Distribution", "Basis"],
    rows: [
      ["Product energy factors (multiplier)", "1.00", "U(0.97, 1.03)", "Density and NCV variation"],
      ["Duqm product factor (ktoe/kbbl)", "0.130", "U(0.125, 0.135)", "Middle-distillate slate"],
      ["Refinery net efficiency η~ref~", "0.95", "Tri(0.92, 0.95, 0.98)", "Szklo and Schaeffer (2007)"],
      ["LNG plant efficiency η~LNG~", "0.905", "U(0.88, 0.93)", "Lee et al. (2018)"],
      ["Chemical feedstock gas (ktoe)", f(c.chem), "U(1,400, 2,300)", "Plant capacities × 20 GJ/t"],
      ["Oil-field gas combusted (share)", f(c.own_share, 2), `Tri(0.20, ${f(c.own_share, 2)}, 0.75)`, "Calibration (C): EI; GCP upper"],
      ["LNG and refinery losses combusted", "0.90", "U(0.80, 1.00)", "Plant fuel vs. losses"],
      ["Grid fleet efficiency η~pp~", "0.45", "Tri(0.40, 0.45, 0.50)", "CCGT-dominated fleet"],
      ["Displaced plant efficiency η~marg~", "0.45", "Tri(0.35, 0.45, 0.55)", "OCGT–CCGT range"],
      ["Non-energy share of naphtha/other", "0.80", "U(0.60, 1.00)", "Petrochemicals, bitumen, lubricants"],
      ["LPG used by households", "0.70", "U(0.50, 0.90)", "Cooking demand"],
      ["Jet fuel in retail (kbbl); international share", "6,000; 0.90", "U(4,000, 9,000); U(0.80, 0.95)", "Airport throughput"],
      ["LNG price; domestic gas price; liquefaction cost (USD/MMBtu)", "10; 3; 1", "U(6, 14); U(1.5, 4.5); U(0.5, 1.5)", "Market range; Fattouh and El-Katiri (2013)"],
    ] },
  { type: "h2", text: "2.7. Time series and decomposition" },
  { type: "p", text: "For 2015–2024 we use primary energy and gas consumption from the EI, electricity from Ember and CO₂ from fuel combustion and flaring from the GCP, compiled by Our World in Data (Energy Institute, 2025; Ember, 2026; Our World in Data, 2026). Real GDP is extended beyond 2022 with official growth rates of 1.3% (2023) and 1.7% (2024) (IMF, 2024; Ministry of Finance, 2025). The change in CO₂ is decomposed with the additive LMDI-I method (Ang, 2015) applied to the Kaya identity (Kaya and Yokobori, 1997):" },
  { type: "eq", n: 6, text: "C = P × (G/P) × (E/G) × (C/E) ,   ΔC~x~ = [(C~T~ − C~0~)/(ln C~T~ − ln C~0~)] × ln(x~T~/x~0~)" },
  { type: "p", text: "where *P* is population, *G* real GDP, *E* primary energy and *C* CO₂; *x* denotes each factor." },
  { type: "h2", text: "2.8. Rent incidence and the dual dividend" },
  { type: "p", text: "Each unit of domestically used gas is valued at its export opportunity cost: the LNG price multiplied by the liquefaction efficiency, less the liquefaction cost and the regulated domestic price. GCC domestic gas prices have been set administratively at USD 0.75–3/MMBtu (Fattouh and El-Katiri, 2013). Oman's industrial price was raised to USD 3/MMBtu in 2015 (Gulf News, 2013), and we vary it between 1.5 and 4.5:" },
  { type: "eq", n: 7, text: "r = P~LNG~ × η~LNG~ − c~liq~ − P~dom~ ,   Rent~s~ = Q~s~ × r" },
  { type: "p", text: "where *Q*~s~ is the gas used by sector *s* (gross MMBtu). The rent preserved by renewables is the freed gas multiplied by *r*. These are gross opportunity costs that assume export outlets are available; they indicate the scale of implicit transfers, not realisable revenue." },

  // ================================================================== 3
  { type: "h1", text: "3. Results" },
  { type: "h2", text: "3.1. The reconciled 2025 energy balance" },
  { type: "p", text: `Table 5 presents the reconciled balance, and Fig. 2 traces the corresponding flows. Indigenous production is ${f(c.production)} ktoe: crude oil and condensate ${pct(c.crude_prod, c.production)}%, marketable gas ${pct(c.gas_marketable, c.production)}% and solar and wind ${pct(c.re, c.production)}%. Supply-side TPES is ${f(c.tpes_supply)} ktoe. Adding back the crude statistical difference of ${f(-c.sd_crude)} ktoe gives use-side TPES of ${f(c.tpes)} ktoe. TFC is ${f(c.tfc)} ktoe. Apart from the crude SD, the only residual is ${f(c.sd_gas, 1)} ktoe in natural gas.` },
  { type: "balance" },
  F(2, "Fig02_sankey.png", "Energy flows in Oman's reconciled 2025 balance (ktoe, NCV). The grey source ribbon is the crude statistical difference."),
  { type: "h2", text: "3.2. Closure, calibration and validation" },
  { type: "p", text: `Fig. 3 and Table 6 document the diagnostics. The as-compiled TPES of 41,762 ktoe changes through seven corrections (Fig. 3b): primary electricity ${f(st["Primary electricity = solar & wind"])}, NCV basis for gas ${f(st["Gas on NCV basis"])}, exclusion of reinjection ${f(st["Reinjection excluded"])}, LNG factor ${f(st["LNG exports at 1.177 toe/t"])}, product-specific factors +${f(st["Product-specific factors (exports)"])}, aviation bunkers ${f(st["Aviation bunkers"])} and the crude statistical difference +${f(st["Crude statistical difference"])} ktoe. The net change is ${pct(c.tpes - 41761.7, 41761.7)}%.` },
  { type: "p", text: `Validation uses data not involved in any calibration (Fig. 3c). Recorded production (${f(val.production_kbd)} kb/d) lies within 1% of independent crude and condensate estimates (${f(val.ext_production_kbd)} kb/d). Generation (${f(val.gen_ours / 1000, 1)} TWh) lies within ${f(Math.abs(val.gen_ours / val.gen_ember25 - 1) * 100, 1)}% of Ember's 2025 value (${f(val.gen_ember25 / 1000, 1)} TWh). Domestic oil use implied by plant-level refinery output (inland use, bunkers and refinery fuel: ${f(val.oil_ours / 1000, 1)} Mtoe) lies within ${f((val.oil_ours / val.oil_ei25[0] - 1) * 100, 0)}% of EI oil consumption extrapolated to 2025 (${f(val.oil_ei25[0] / 1000, 1)} Mtoe). This last test supports the observed refinery output, and hence use-side TPES. Had output been double-counted by the size of the crude gap, domestic oil supply would become negative, which is inconsistent with independently measured consumption. Gas consumption matches the EI series by construction (calibration), so it is not evidence of accuracy. Petroleum CO₂ (${f(c.co2_fuel["Petroleum products"], 1)} Mt) exceeds the GCP oil series (${f(val.gcp_oil25[0], 1)} Mt, 2025-extrapolated). However, the GCP figure is inconsistent with EI's own oil consumption data, and road transport alone accounts for ${f(co2["1.A.3 Transport"], 1)} Mt on the basis of metered retail sales.` },
  F(3, "Fig03_diagnostics.png", "Diagnostics. (a) Refinery output by plant group against nameplate capacity, and recorded crude supply. (b) Reconciliation of TPES from the as-compiled to the use-side reconciled balance. (c) Validation (V) against data not used in calibration, and the calibration target (C); external values are 2025 or extrapolated to 2025."),
  { type: "table", n: 6, caption: "Diagnostic findings and treatments.", widths: [2200, 2400, 2600, 2160],
    header: ["Issue", "Test and finding", "Treatment", "Effect on TPES (ktoe)"],
    rows: [
      ["Thermal electricity recorded as primary energy", "IRES definition", "Primary electricity = solar and wind", f(st["Primary electricity = solar & wind"])],
      ["Gas factor on gross basis; NCV emission factors", "Calorific consistency", "All gas on NCV (0.9 × GCV)", f(st["Gas on NCV basis"])],
      ["Oil-field gas includes reinjection", "C: EI gas consumption", `${f(c.own_share * 100, 0)}% combusted (20–75%); rest excluded`, f(st["Reinjection excluded"])],
      ["LNG feed implies η = 96.8%", "T2: above plant range", "Feed from output, η 88–93%", "0 (allocation)"],
      ["LNG factor 1.09 toe/t", "NCV of LNG", `${f(R.lng_toe_t, 3)} toe/t`, f(st["LNG exports at 1.177 toe/t"])],
      ["Single product factor 0.145 ktoe/kbbl", "Exceeds crude factor", "Product-specific factors", "+" + f(st["Product-specific factors (exports)"])],
      ["Jet fuel counted as domestic", "IRES bunker convention", "International share to bunkers", f(st["Aviation bunkers"])],
      ["Chemical feedstock counted as fuel", "Plant capacities", `${f(c.chem)} ktoe to non-energy use`, "0 (allocation)"],
      [`Refinery intake exceeds crude supply by ${f(sdKbd)} kb/d`, "T2 plant-level; V tests; H0–H2 rejected", "Explicit crude SD; use-side TPES", "+" + f(st["Crude statistical difference"])],
      [`Power-and-water fleet η = ${f(c.eta_pp_implied * 100, 1)}%`, "T2: below CCGT range", "Desalination and unattributed separated", "0 (allocation)"],
    ] },
  { type: "h2", text: "3.3. Headline indicators and supply structure" },
  { type: "p", text: `Table 7 compares the headline indicators. On the use side, the SSR is ${f(c.ssr, 0)}% (90% CI ${ci("ssr", 0)}%). On the supply side it is ${f(c.ssr_supply, 0)}%, and under the GCP calibration ${f(cal.ssr_gcp_cal, 0)}%; the as-compiled value was 252.8%. Under every variant, Oman produces more than twice its primary requirement.` },
  { type: "table", n: 7, caption: "Headline indicators, 2025 (ktoe, NCV).", widths: [2900, 1500, 2300, 1300, 1360],
    header: ["Indicator", "As compiled", "Reconciled, use side (90% CI)", "Supply side", "GCP calibration"],
    rows: [
      ["Indigenous production", "105,585.5", `${f(c.production)} (${ci("production")})`, f(c.production), "–"],
      ["TPES", "41,761.7", `${f(c.tpes)} (${ci("tpes")})`, f(c.tpes_supply), f(cal.tpes_gcp_cal)],
      ["TFC", "25,481.7", `${f(c.tfc)} (${ci("tfc")})`, f(c.tfc), "–"],
      ["Self-sufficiency ratio (%)", "252.8", `${f(c.ssr, 1)} (${ci("ssr", 1)})`, f(c.ssr_supply, 1), f(cal.ssr_gcp_cal, 1)],
      ["Energy intensity (toe/RO million)", "1,040.7", `${f(c.intensity, 0)} (${ci("intensity", 0)})`, f(c.tpes_supply * 1000 / 40130, 0), "–"],
      ["Renewable share of TPES (%)", "0.93", f(c.re_share_tpes, 2), f(c.re / c.tpes_supply * 100, 2), "–"],
      ["Fuel-combustion CO₂ (Mt)", "91.48", `${f(c.co2_total, 1)} (${ci("co2_total", 1)})`, f(c.co2_total, 1), f(gcpCal, 1)],
    ] },
  F(4, "Fig04_supply.png", "Supply, 2025. (a) Indigenous production, with reinjected gas excluded. (b) Use-side TPES by commodity, including the crude statistical difference; negative values denote net exports and bunkers. (c) Uses of TPES."),
  { type: "p", text: `Fig. 5 shows the crude account and the Sohar–Mina Al Fahal product slate, which is dominated by diesel (33%) and naphtha and other products (23%). Of gross gas production on an NCV basis, ${pct(c.lng_feed, c.gas_gross)}% is liquefied, ${pct(c.gas_power, c.gas_gross)}% goes to power-and-water plants, ${pct(c.ind_fuel, c.gas_gross)}% is industrial fuel, ${pct(c.chem, c.gas_gross)}% is chemical feedstock, ${pct(c.own, c.gas_gross)}% is burnt in upstream operations and ${pct(c.reinj, c.gas_gross)}% is reinjected (Fig. 6a). The reconciled LNG feed is 7% above the reported estimate (Fig. 6b).` },
  F(5, "Fig05_oil.png", "Oil, 2025. (a) Crude account: recorded supply to refineries, intake implied by output, and refinery output by plant group (ktoe). (b) Sohar–Mina Al Fahal product slate by energy content, with product-specific factors."),
  F(6, "Fig06_gas.png", "Natural gas, 2025 (NCV). (a) Gross production by use; the hatched segment is power-and-water plant fuel not attributable to grid electricity. (b) LNG feed gas as reported and as reconciled, with LNG output."),
  { type: "h2", text: "3.4. Final consumption" },
  { type: "p", text: `Table 8 and Fig. 7 present TFC by sector and carrier. Industry is the largest energy user (${f(s.Industrial)} ktoe; ${pct(s.Industrial, c.tfc)}%). Non-energy use, comprising chemical feedstock gas and petroleum feedstocks, accounts for ${pct(s["Non-energy use"], c.tfc)}%, transport for ${pct(s.Transport, c.tfc)}% and buildings for ${pct(s.Residential + s.Commercial + s.Government, c.tfc)}%. TFC depends on observed refinery output and product exports, not on the crude reconciliation; its 90% interval is ${ci("tfc")} ktoe. The largest allocation uncertainty is the split of non-energy use (90% CI ${ci("ne_total")} ktoe).` },
  { type: "table", n: 8, caption: "Total Final Consumption by sector and carrier, 2025 (ktoe, NCV).", widths: [2160, 1200, 1300, 1150, 1100, 1250, 1200],
    header: ["Sector", "Gas", "Petroleum", "Electricity", "Coal", "Total", "Share (%)"],
    rows: [
      ["Industrial", f(c.ind_fuel), f(petInd), f(es.Industrial), f(c.coal), f(s.Industrial), pct(s.Industrial, c.tfc)],
      ["Transport", "–", f(s.Transport), "–", "–", f(s.Transport), pct(s.Transport, c.tfc)],
      ["Non-energy use", f(c.chem), f(c.ne_oil), "–", "–", f(s["Non-energy use"]), pct(s["Non-energy use"], c.tfc)],
      ["Residential", "–", f(petRes), f(es.Residential), "–", f(s.Residential), pct(s.Residential, c.tfc)],
      ["Commercial", "–", "–", f(es.Commercial), "–", f(s.Commercial), pct(s.Commercial, c.tfc)],
      ["Government", "–", "–", f(es.Government), "–", f(s.Government), pct(s.Government, c.tfc)],
      ["Agriculture & other", "–", "–", f(es["Agriculture & other"]), "–", f(s["Agriculture & other"]), pct(s["Agriculture & other"], c.tfc)],
      ["Total", f(c.ind_fuel + c.chem), f(tfcProd), f(3872.8), f(c.coal), f(c.tfc), "100.0"],
    ] },
  F(7, "Fig07_sectoral.png", "Final consumption, 2025. (a) TFC by sector and carrier. (b) Electricity consumption by sector. (c) Allocation of domestic petroleum products, including aviation bunkers."),
  { type: "p", text: `Of the 45,033 GWh of electricity consumed, households use 41.4%, commercial users 27.0%, industry 18.1% and government 10.1% (Fig. 7b). Renewable generation reached 4,509 GWh, or ${f(c.re_share_gen, 2)}% of generation, against 4.89% in 2024 (Fig. 8); three photovoltaic plants supplied 97.2% of it. Ember's preliminary 2025 estimate (${f(R.ember_re25, 1)}%) carries forward 2024 solar output and misses new capacity that appears in the plant-level data. Reaching OPWP's 30% target requires a gain of 4.2 percentage points a year to 2030.` },
  F(8, "Fig08_electricity.png", "Electricity, 2025. (a) Electricity balance. (b) Renewable generation by plant. (c) Renewable share of generation, 2015–2025, with the 2030 targets."),
  { type: "h2", text: "3.5. CO₂ emissions" },
  { type: "p", text: `Fuel-combustion CO₂ emissions are ${f(c.co2_total, 1)} Mt (90% CI ${ci("co2_total", 1)}; median ${f(mc.co2_total.p50, 1)}), or ${f(c.co2_per_capita, 1)} t per capita (Table 9; Fig. 9). The distribution is skewed upwards because higher combusted shares of oil-field gas cannot be excluded; the GCP calibration gives ${f(gcpCal, 1)} Mt. Energy industries (1.A.1) account for ${f(ea, 1)} Mt. Of this, ${f(co2["1.A.1.a Electricity (grid)"], 1)} Mt comes from grid electricity, ${f(co2["1.A.1.a Desalination heat & unattributed"], 1)} Mt from desalination and unattributed plant fuel, and ${f(newCats, 1)} Mt from refining, liquefaction and upstream fuel, three categories absent from the as-compiled inventory. Manufacturing contributes ${f(co2["1.A.2 Manufacturing industries"], 1)} Mt and transport ${f(co2["1.A.3 Transport"], 1)} Mt; natural gas accounts for ${pct(c.co2_fuel["Natural gas"], c.co2_total, 0)}%. International bunkers add a memo item of ${f(c.memo_bunkers_co2, 1)} Mt.` },
  { type: "table", n: 9, caption: "CO₂ emissions from fuel combustion by IPCC category, 2025 (Mt).", widths: [3600, 1700, 1700, 2360],
    header: ["IPCC category", "Reconciled", "Share (%)", "As compiled"],
    rows: [
      ...Object.entries(co2).map(([k, v]) => [k, f(v, 2), pct(v, c.co2_total), {
        "1.A.1.a Electricity (grid)": "32.82*", "1.A.1.a Desalination heat & unattributed": "*",
        "1.A.1.b Petroleum refining": "–", "1.A.1.c LNG liquefaction": "–", "1.A.1.c Oil & gas extraction": "–",
        "1.A.2 Manufacturing industries": "27.81", "1.A.3 Transport": "13.29", "1.A.4 Residential": "0.95"}[k]]),
      ["Unallocated petroleum residual", "–", "–", "16.60"],
      ["Total", f(c.co2_total, 2), "100.0", "91.48"],
      ["Memo: international bunkers", f(c.memo_bunkers_co2, 2), "", "–"],
    ],
    note: "*All power-and-water plant gas was attributed to electricity in the as-compiled inventory, on a gross calorific basis." },
  F(9, "Fig09_emissions.png", "CO₂ emissions from fuel combustion, 2025. (a) By IPCC category. (b) By fuel. (c) End-use attribution, with grid-electricity emissions allocated by consumption. *Energy sector: upstream, LNG, refining, desalination and unattributed fuel."),
  { type: "h2", text: "3.6. Emission trends and drivers, 2015–2024" },
  { type: "p", text: `CO₂ from fuel combustion and flaring rose from ${f(ts15.co2, 1)} Mt in 2015 to ${f(ts24.co2, 1)} Mt in 2024 (+${f(d["2015-2024"].total, 1)} Mt), and the gas share rose from ${pct(ts15.gas_co2, ts15.co2, 0)}% to ${pct(ts24.gas_co2, ts24.co2, 0)}% (Fig. 10a). The LMDI decomposition (Table 10; Fig. 10b) attributes the increase to population growth (+${f(d["2015-2024"].pop, 1)} Mt) and rising energy intensity of GDP (+${f(d["2015-2024"].ei, 1)} Mt). Falling real GDP per capita (${f(d["2015-2024"].aff, 1)} Mt) and declining carbon intensity (${f(d["2015-2024"].ci, 1)} Mt) partly offset them. The energy-intensity effect accelerated after 2019 (+${f(d["2019-2024"].ei, 1)} Mt in 2019–2024 against +${f(d["2015-2019"].ei, 1)} Mt in 2015–2019), coinciding with gas-intensive industrial expansion and the commissioning of Duqm. Emissions grew while real GDP per capita fell, so there is no evidence of decoupling (Stern, 2004). The reconciled 2025 inventory excludes flaring and is built from national activity data, so it is not strictly comparable with the series; its central value lies close to the 2024 series level excluding flaring.` },
  { type: "table", n: 10, caption: "LMDI decomposition of the change in CO₂ from fuel combustion and flaring (Mt).", widths: [2160, 1440, 1440, 1440, 1440, 1440],
    header: ["Period", "Population", "GDP per capita", "Energy intensity", "Carbon intensity", "Total"],
    rows: Object.entries(d).map(([k, v]) => [k, f(v.pop, 2), f(v.aff, 2), f(v.ei, 2), f(v.ci, 2), f(v.total, 2)]) },
  F(10, "Fig10_trends_lmdi.png", "Emission trends. (a) CO₂ from fuel combustion and flaring by fuel, 2015–2024 (GCP), and the reconciled 2025 inventory with its 90% interval. (b) LMDI decomposition of the change in CO₂."),
  { type: "h2", text: "3.7. Uncertainty" },
  { type: "p", text: `The 90% intervals are ${ci("tpes")} ktoe for TPES, ${ci("ssr", 0)}% for the SSR and ${ci("co2_total", 1)} Mt for CO₂ (Fig. 11). The combusted share of oil-field gas dominates both the SSR (ρ = ${f(R.sens.ssr.own_comb_share, 2)}) and CO₂ (ρ = +${f(R.sens.co2_total.own_comb_share, 2)}). Refinery efficiency and the non-energy share of naphtha follow. Field-level data on reinjection and fuel gas would remove most of the remaining uncertainty.` },
  F(11, "Fig11_uncertainty.png", "Monte Carlo uncertainty (10,000 draws). (a–c) Distributions of TPES, the self-sufficiency ratio and CO₂; solid lines mark the central estimate, dotted lines the 90% interval. (d–e) Spearman rank correlations between parameters and outputs."),

  // ================================================================== 4
  { type: "h1", text: "4. Discussion: the political economy of Oman's transition" },
  { type: "h2", text: "4.1. Rent incidence in a gas-based rentier economy" },
  { type: "p", text: `Rentier theory predicts that the state distributes resource rents to sustain political allegiance; in energy exporters much of this distribution occurs off-budget, through energy sold below its opportunity cost (Beblawi and Luciani, 1987; Krane, 2019). The reconciled accounts allow the transfer to be measured. At an LNG price of USD 10/MMBtu, net of liquefaction losses and costs, domestic gas use in 2025 carried an implicit rent of USD ${f(c.rent_total, 1)} billion, or ${f(c.rent_share_gdp, 1)}% of GDP (90% CI ${ci("rent_share_gdp", 1)}%). Power-and-water plants received ${f(c.rent_foregone["Power & water plants"], 1)} billion, industry (fuel and feedstock) ${f(c.rent_foregone["Industry (fuel & feedstock)"], 1)} billion and upstream operations ${f(c.rent_foregone["Upstream own use"], 1)} billion (Fig. 12a). The explicit electricity subsidy in the 2025 budget is RO 520 million, or USD ${f(subsidyUSD, 2)} billion (Gulf News, 2025). The implicit gas rent is several times larger and reaches consumers mainly through electricity tariffs and industrial gas prices. This makes tariff and gas-price reform politically sensitive, and it is consistent with the argument of Al-Sarihi and Cherni (2023) that renewables are embraced in forms that leave these distributional channels intact.` },
  F(12, "Fig12_rents_capacity.png", "Rents and scale. (a) Implicit gas rent transferred to domestic users in 2025 at three LNG prices, compared with the explicit electricity subsidy. (b) Additional VRE capacity required for a 30% renewable share by 2030, by demand growth and capacity factor, compared with the capacity required for the 2030 hydrogen target."),
  { type: "h2", text: "4.2. The dual dividend of renewables" },
  { type: "p", text: `In 2025 renewables avoided ${f(c.avoided, 2)} MtCO₂ (90% CI ${ci("avoided", 2)}) and freed ${f(c.gas_freed_bcm, 2)} bcm of gas, preserving an export rent of USD ${f(c.rent_preserved, 2)} billion (${ci("rent_preserved", 2)}) (Fig. 13). With 30% renewables at constant generation, avoided emissions would reach 5.6–8.8 Mt and the preserved rent USD ${f(rent30(6), 2)}–${f(rent30(14), 2)} billion per year. This dual dividend is specific to exporters, aligning climate policy with the fiscal interests of the rentier state, whereas importers benefit mainly through lower import bills (Al-Maamary et al., 2017b; Szalai et al., 2025). It has two limitations. Gas that is exported or redirected to new industry is still burnt elsewhere, so global emissions fall by less than the territorial saving (Davis et al., 2011; Liu et al., 2026). And the preserved rent is small compared with the implicit rent transferred domestically: renewables protect rents at the margin but do not alter how they are distributed.` },
  F(13, "Fig13_dual_dividend.png", "The dual dividend. (a) Avoided CO₂ as a function of renewable share for the central and bounding displaced-plant efficiencies, with 2025 generation held constant. (b) Export rent preserved by freed gas by renewable share and LNG price (domestic price USD 3/MMBtu; liquefaction cost USD 1/MMBtu)."),
  { type: "h2", text: "4.3. Demand-side management and energy efficiency" },
  { type: "p", text: `Rising energy intensity added ${f(d["2015-2024"].ei, 1)} Mt of CO₂ between 2015 and 2024, more than renewables could abate at the 30% target. Energy efficiency has been under-prioritised in the GCC because administered prices weaken the incentive to conserve (Fattouh and El-Katiri, 2013; Almasri and Narayan, 2021). Partial indicators such as energy per unit of GDP conflate structural change with efficiency (Patterson, 1996). Total-factor energy efficiency benchmarking offers a better basis for negotiated agreements with the industrial gas users identified here (Hu and Wang, 2006; Tanaka, 2008). Buildings consume 78.5% of electricity, largely for cooling, and cost-reflective tariffs with targeted household support and building codes are the instruments most directly supported by the evidence. Each additional percentage point of annual demand growth raises the VRE capacity needed for the 30% target by about 0.3 GW (Fig. 12b).` },
  { type: "h2", text: "4.4. Hydrogen and additionality" },
  { type: "p", text: "Hydrom's 2030 target of 1.0–1.25 Mt of hydrogen requires about 55–69 TWh of electricity, or 16–20 GW of dedicated capacity at a hybrid capacity factor of 0.40. This compares with an implied 2025 VRE fleet of about 1.7 GW and 3.5–7 GW of grid additions for the 30% target (Fig. 12b; IEA, 2023b; Marzouk, 2024). At this scale, the accounting question becomes central: a reconciled annual balance is needed to verify that electrolytic electricity is additional and does not raise gas burn elsewhere in the system." },
  { type: "h2", text: "4.5. Implications for energy statistics in producer states" },
  { type: "p", text: "Three lessons generalise. First, calorific basis matters: mixing gross gas data with net emission factors and LNG factors overstated gas CO₂ by about 10% and produced an implausible liquefaction efficiency. Second, transformation flows must be checked plant by plant; national aggregates concealed both a feasible refinery output and an infeasible crude supply. Third, parameters calibrated to international series must not be presented as validated by them. Producer states should report refinery intake, reinjection, chemical feedstock and power-and-water fuel splits as metered quantities, and international compilers should request them explicitly (UNSD, 2018; Kuunifaa et al., 2026)." },

  // ================================================================== 5
  { type: "h1", text: "5. Policy implications and limitations" },
  { type: "h2", text: "5.1. Policy recommendations" },
  { type: "p", text: "Fig. 14 organises the recommendations, and Table 11 links each instrument to its evidence." },
  F(14, "Fig14_policy.png", "Policy framework linking the reconciled evidence layer to supply-side, demand-side and institutional instruments."),
  { type: "table", n: 11, caption: "Policy instruments and supporting evidence.", widths: [2700, 3100, 2000, 1560],
    header: ["Instrument", "Evidence", "Lead institutions", "Horizon"],
    rows: [
      ["Meter refinery crude intake, reinjection and plant fuel splits", `Crude SD ${f(-c.sd_crude / 1000, 1)} Mtoe; oil-field share 20–75%; ${f(c.gas_pw_other / 1000, 1)} Mtoe unattributed`, "Ministry of Energy and Minerals; NCSI; operators", "Short term"],
      ["Report all gas on a stated calorific basis", "GCV/NCV mixing biased CO₂ by ~10%", "NCSI", "Short term"],
      ["Adopt the reconciled balance for NDC reporting", `Inventory of ${f(c.co2_total, 1)} Mt with 1.A.1 categories previously missing`, "Environment Authority; NCSI", "Short term"],
      ["Gradual domestic gas price path towards opportunity cost", `Implicit rent ≈ ${f(c.rent_share_gdp, 1)}% of GDP`, "Ministry of Finance; regulator", "Medium term"],
      ["Value freed gas in renewable procurement", `${f(c.gas_freed_bcm, 2)} bcm freed in 2025`, "OPWP; Ministry of Finance", "Short term"],
      ["Industrial efficiency benchmarking and fuel switching", `Industry ${pct(s.Industrial, c.tfc, 0)}% of TFC; ${f(co2["1.A.2 Manufacturing industries"], 1)} Mt CO₂`, "Ministry of Energy and Minerals", "Medium term"],
      ["Additionality rules for hydrogen", "16–20 GW for hydrogen versus 3.5–7 GW for the grid", "Hydrom; OPWP", "Medium term"],
    ] },
  { type: "h2", text: "5.2. Limitations and future work" },
  { type: "p", text: `Table 12 catalogues the limitations. The most important is the crude statistical difference of ${f(-c.sd_crude)} ktoe (${f(sdKbd)} kb/d). It is reported, not resolved, and its location (unrecorded imports, stock draws or recording of terminal liftings) can be established only with metered refinery intake by crude origin. The combusted share of oil-field gas is calibrated, not measured, and its range spans a factor of nearly four. The split of power-and-water fuel and the feedstock estimates rest on engineering parameters. The Tier 1 inventory excludes flaring (about 3.8 Mt in 2024 according to the GCP), venting, fugitive methane and process emissions (Elvidge et al., 2018). The 2015–2024 decomposition uses international series whose definitions differ from the national balance. Future work should rebuild a national time series on the reconciled basis and move key categories to Tier 2.` },
  { type: "table", n: 12, caption: "Remaining limitations and required data.", widths: [2800, 3300, 3260], header: ["Limitation", "Effect", "Required data"],
    rows: [
      [`Crude SD (${f(sdKbd)} kb/d) unattributed`, "Supply-side and use-side TPES differ by 30%", "Refinery intake by crude origin; Ras Markaz stock data"],
      ["Reinjection not separated from fuel use", "Dominant source of CO₂ and SSR uncertainty", "Field-level reinjection, EOR steam and fuel gas"],
      ["Power-and-water fuel split", `${f(c.gas_pw_other / 1000, 1)} Mtoe not attributed to grid electricity`, "Plant-level fuel, power and water output"],
      ["Chemical feedstock and naphtha non-energy use", `Non-energy use ${ci("ne_total")} ktoe`, "Plant feedstock statistics"],
      ["Duqm product slate", "Product factor 0.125–0.135", "Duqm output by product"],
      ["Tier 1 scope", "Flaring, venting, fugitive and process CO₂ excluded", "Tier 2/3 upstream, ammonia and cement inventory"],
    ] },

  // ================================================================== 6
  { type: "h1", text: "6. Conclusions" },
  { type: "p", text: `Applying standard closure checks plant by plant to Oman's 2025 energy accounts revealed problems that arithmetic closure concealed. Gross and net calorific bases had been mixed. Reinjected gas and chemical feedstock had been counted as fuel. Thermal electricity had been counted as primary energy, and the reported LNG feedstock was implausible. Refinery output is consistent with plant capacities and independent consumption data, but recorded crude supply falls ${f(sdKbd)} kb/d short of it, a gap reported here as an explicit statistical difference. On a net-calorific basis, Oman produces ${f(c.production / 1000, 1)} Mtoe against use-side primary supply of ${f(c.tpes / 1000, 1)} Mtoe, a self-sufficiency ratio of ${f(c.ssr, 0)}%. Fuel-combustion emissions are ${f(c.co2_total, 0)} MtCO₂ (${ci("co2_total", 0)}). Between 2015 and 2024 emissions grew by ${f(d["2015-2024"].total, 1)} Mt, driven by population and energy intensity, with no evidence of decoupling.` },
  { type: "p", text: `Renewables reached ${f(c.re_share_gen, 2)}% of generation in 2025, avoiding about 2 MtCO₂ and freeing about 1 bcm of gas. This dual dividend aligns climate policy with the fiscal interests of a rentier state, but it is small relative to the implicit gas rent of about ${f(c.rent_share_gdp, 0)}% of GDP transferred to domestic users. Deep decarbonization will therefore depend on reforming the pricing and statistical institutions through which that rent is distributed and measured, and transparent annual energy accounts are a precondition for verifying progress towards Oman Vision 2040 and net zero by 2050.` },
];

